def saveSettings(self, groupName=None):
        """ Writes the registry items into the persistent settings store.
        """
        if groupName is None:
            groupName = self.groupName
        if groupName is None:
            raise ValueError("Group name not specified")
        settings = self.settings
        if settings is None:
            raise ValueError("No settings to save")
        if self.settingsFile is None:
            raise ValueError("No settings file specified")
        if self.settingsFile == "":
            raise ValueError("Empty settings file")
        if not os.path.exists(self.settingsFile):
            raise IOError("Settings file does not exist")
        if not os.path.isfile(self.settingsFile):
            raise IOError("Settings file is not a file")
        if not os.access(self.settingsFile, os.W_OK):
            raise IOError("Settings file is not writable")
        if groupName not in settings:
            raise ValueError("Settings group not found")
        settings = settings[groupName]
        if settings is None:
            raise ValueError("No settings to save")
        try:
            with open(self.settingsFile, "w") as f:
                f.write(json.dumps(settings, indent=4))
        except IOError as e:
            raise IOError("Unable to write to settings file: %s" % (str(e)))

